const LanguageContext = createContext(null);

export function LanguageProvider({ children }) {
  const [language, setLanguage] = useState(() => {
    const saved = localStorage.getItem('nexus_language');
    return messages[saved] ? saved : 'en';
  });
  useEffect(() => {
    document.documentElement.lang = language;
    document.title = `${workspaceCopy[language].brandName} | ${workspaceCopy[language].browserTitle}`;
  }, [language]);
  const changeLanguage = (code) => {
    if (!messages[code]) return;
    localStorage.setItem('nexus_language', code);
    setLanguage(code);
    document.documentElement.lang = code;
  };
  const value = useMemo(() => ({
    language,
    changeLanguage,
    t: (key) => {
      const value = workspaceCopy[language][key] || messages[language][key] || sampleContentCopy[language]?.[key] || workspaceCopy.en[key] || messages.en[key] || key;
      return typeof value === 'string' ? value.replace(/NEXUS/g, workspaceCopy[language].brandName) : value;
    },
    languages: LANGUAGES,
  }), [language]);
  return <LanguageContext.Provider value={value}>{children}</LanguageContext.Provider>;
}

export function useLanguage() {
  const context = useContext(LanguageContext);
  if (!context) throw new Error('useLanguage must be used inside LanguageProvider');
  return context;
}
